-- Disposable UAT baseline for the delivery-only Health Rider scope.
CREATE TABLE `users` (`id` CHAR(26) NOT NULL, `username` VARCHAR(100) NOT NULL, `passwordHash` VARCHAR(255) NOT NULL, `displayName` VARCHAR(255) NOT NULL, `role` ENUM('pharmacy','coordinator','rider','admin','auditor') NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `users_username_key`(`username`), PRIMARY KEY (`id`));
CREATE TABLE `rider_profiles` (`id` CHAR(26) NOT NULL, `userId` CHAR(26) NOT NULL, `riderCode` VARCHAR(100) NOT NULL, `employmentCategory` ENUM('internal','external') NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `rider_profiles_userId_key`(`userId`), UNIQUE INDEX `rider_profiles_riderCode_key`(`riderCode`), PRIMARY KEY (`id`));
CREATE TABLE `delivery_zones` (`id` CHAR(26) NOT NULL, `subdistrictCode` VARCHAR(32) NOT NULL, `villageCode` VARCHAR(32) NOT NULL, `displayName` VARCHAR(255) NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `delivery_zones_subdistrictCode_villageCode_key`(`subdistrictCode`, `villageCode`), PRIMARY KEY (`id`));
CREATE TABLE `eligibility_rules` (`id` CHAR(26) NOT NULL, `name` VARCHAR(255) NOT NULL, `enabled` BOOLEAN NOT NULL DEFAULT true, `definition` JSON NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `eligibility_rules_name_key`(`name`), PRIMARY KEY (`id`));
CREATE TABLE `delivery_requests` (`id` CHAR(26) NOT NULL, `hosVisitNumber` VARCHAR(100) NULL, `hn` VARCHAR(100) NOT NULL, `patientName` VARCHAR(255) NOT NULL, `patientAge` INTEGER NULL, `telephone` VARCHAR(100) NULL, `deliveryAddress` TEXT NOT NULL, `deliveryZoneId` CHAR(26) NOT NULL, `deliveryVersion` INTEGER NOT NULL DEFAULT 1, `createdById` CHAR(26) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, INDEX `delivery_requests_hn_createdAt_idx`(`hn`, `createdAt`), PRIMARY KEY (`id`));
CREATE TABLE `delivery_attempts` (`id` CHAR(26) NOT NULL, `deliveryRequestId` CHAR(26) NOT NULL, `riderId` CHAR(26) NULL, `status` ENUM('prepared','claimed','in_transit','delivered','delivery_failed','return_required','returned','sync_review') NOT NULL DEFAULT 'prepared', `claimedAt` DATETIME(3) NULL, `pickedUpAt` DATETIME(3) NULL, `deliveredAt` DATETIME(3) NULL, `failedAt` DATETIME(3) NULL, `failureReason` VARCHAR(100) NULL, `returnedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `package_qr_tokens` (`id` CHAR(26) NOT NULL, `deliveryAttemptId` CHAR(26) NOT NULL, `tokenHash` CHAR(64) NOT NULL, `expiresAt` DATETIME(3) NOT NULL, `invalidatedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `package_qr_tokens_tokenHash_key`(`tokenHash`), PRIMARY KEY (`id`));
CREATE TABLE `delivery_evidence` (`id` CHAR(26) NOT NULL, `deliveryAttemptId` CHAR(26) NOT NULL, `recipientRelation` VARCHAR(100) NOT NULL, `photoPath` VARCHAR(1024) NOT NULL, `deviceCapturedAt` DATETIME(3) NOT NULL, `serverReceivedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `delivery_evidence_deliveryAttemptId_key`(`deliveryAttemptId`), PRIMARY KEY (`id`));
CREATE TABLE `offline_delivery_events` (`id` CHAR(26) NOT NULL, `eventUuid` CHAR(36) NOT NULL, `deliveryAttemptId` CHAR(26) NOT NULL, `riderId` CHAR(26) NOT NULL, `deliveryVersion` INTEGER NOT NULL, `eventType` VARCHAR(100) NOT NULL, `payload` JSON NOT NULL, `deviceCapturedAt` DATETIME(3) NOT NULL, `serverReceivedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `offline_delivery_events_eventUuid_riderId_key`(`eventUuid`, `riderId`), PRIMARY KEY (`id`));
CREATE TABLE `sync_conflicts` (`id` CHAR(26) NOT NULL, `offlineDeliveryEventId` CHAR(26) NOT NULL, `status` VARCHAR(50) NOT NULL DEFAULT 'pending', `resolution` TEXT NULL, `resolvedById` CHAR(26) NULL, `resolvedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `sync_conflicts_offlineDeliveryEventId_key`(`offlineDeliveryEventId`), PRIMARY KEY (`id`));
CREATE TABLE `audit_events` (`id` CHAR(26) NOT NULL, `actorId` CHAR(26) NOT NULL, `action` VARCHAR(255) NOT NULL, `auditableType` VARCHAR(100) NOT NULL, `auditableId` CHAR(26) NOT NULL, `reason` TEXT NULL, `oldValues` JSON NULL, `newValues` JSON NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `audit_events_auditableType_auditableId_createdAt_idx`(`auditableType`, `auditableId`, `createdAt`), PRIMARY KEY (`id`));
ALTER TABLE `rider_profiles` ADD CONSTRAINT `rider_profiles_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `delivery_requests` ADD CONSTRAINT `delivery_requests_deliveryZoneId_fkey` FOREIGN KEY (`deliveryZoneId`) REFERENCES `delivery_zones`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `delivery_requests` ADD CONSTRAINT `delivery_requests_createdById_fkey` FOREIGN KEY (`createdById`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `delivery_attempts` ADD CONSTRAINT `delivery_attempts_deliveryRequestId_fkey` FOREIGN KEY (`deliveryRequestId`) REFERENCES `delivery_requests`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `delivery_attempts` ADD CONSTRAINT `delivery_attempts_riderId_fkey` FOREIGN KEY (`riderId`) REFERENCES `users`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `package_qr_tokens` ADD CONSTRAINT `package_qr_tokens_deliveryAttemptId_fkey` FOREIGN KEY (`deliveryAttemptId`) REFERENCES `delivery_attempts`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `delivery_evidence` ADD CONSTRAINT `delivery_evidence_deliveryAttemptId_fkey` FOREIGN KEY (`deliveryAttemptId`) REFERENCES `delivery_attempts`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `offline_delivery_events` ADD CONSTRAINT `offline_delivery_events_deliveryAttemptId_fkey` FOREIGN KEY (`deliveryAttemptId`) REFERENCES `delivery_attempts`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
